q=A.w(j,A.bOg(q,B.ab,3,!1,B.ab,B.AF,j,A.a([A.pf(B.amI,k.io(e,"Wer ist Kkaebi?","Who is Kkaebi?","\u0915\u0948\u092c\u0940 \u0915\u094c\u0928 \u0939\u0948?","\u30c8\u30c3\u30b1\u30d3\u3068\u306f\uff1f","\uae68\ube44\ub294 \ub204\uad6c?","\u5409\u9b3c\u662f\u8c01\uff1f")),A.pf(B.akO,k.io(e,"DOK-KEY Anleitung","App Guide",h,"DOK-KEY \u8aac\u660e\u66f8","DOK-KEY \ub3c4\uc6c0\ub9d0","\u7cfb\u7edf\u8bf4\u660e\u4e66"))],s),B.vN),B.k,B.mL,j,j,j,j,j,j,j,j,j,j)
